"""Async Strata client — native async interface wrapping MCP tool calls."""

from __future__ import annotations

import json
import os
import re
from typing import Any

from strata.exceptions import StrataError
from strata.transport.base import Transport
from strata.transport.http import HttpTransport
from strata.transport.stdio import StdioTransport
from strata.types import (
    HistoryEvent,
    IngestResult,
    Memory,
    Project,
    SearchResult,
)


class AsyncStrataClient:
    """Async client for Strata memory operations.

    Usage::

        async with AsyncStrataClient() as s:
            results = await s.search("auth patterns")

        # Or with explicit lifecycle:
        s = AsyncStrataClient()
        await s.connect()
        results = await s.search("auth patterns")
        await s.close()
    """

    def __init__(
        self,
        url: str | None = None,
        token: str | None = None,
        transport: Transport | None = None,
        user: str | None = None,
    ) -> None:
        self._user = user
        self._owns_transport = transport is None

        if transport is not None:
            self._transport = transport
        elif url or os.environ.get("STRATA_URL"):
            self._transport = HttpTransport(
                url=url or os.environ["STRATA_URL"],
                token=token or os.environ.get("STRATA_TOKEN"),
            )
        else:
            self._transport = StdioTransport()

    async def connect(self) -> None:
        """Connect to the Strata MCP server."""
        await self._transport.connect()

    async def close(self) -> None:
        """Close the connection."""
        if self._owns_transport:
            await self._transport.close()

    async def __aenter__(self) -> AsyncStrataClient:
        await self.connect()
        return self

    async def __aexit__(self, *exc: object) -> None:
        await self.close()

    # ── Core CRUD (Mem0-compatible surface) ──────────────────────────

    async def add(
        self,
        text: str,
        *,
        type: str = "learning",
        tags: list[str] | None = None,
        project: str | None = None,
        user: str | None = None,
        user_id: str | None = None,
    ) -> Memory:
        """Store a memory. Returns the created Memory object."""
        args: dict[str, Any] = {"memory": text, "type": type}
        if tags:
            args["tags"] = ",".join(tags)
        if project:
            args["project"] = project
        u = user or user_id or self._user
        if u:
            args["user"] = u

        result = await self._transport.call_tool("store_memory", args)
        return _parse_store_result(result)

    async def search(
        self,
        query: str,
        *,
        limit: int = 20,
        project: str | None = None,
        user: str | None = None,
        user_id: str | None = None,
        format: str = "detailed",
    ) -> list[SearchResult]:
        """Search memories. Returns a list of SearchResult objects."""
        args: dict[str, Any] = {"query": query, "limit": limit, "format": format}
        if project:
            args["project"] = project
        u = user or user_id or self._user
        if u:
            args["user"] = u

        result = await self._transport.call_tool("search_history", args)
        return _parse_search_results(result)

    async def update(
        self,
        id: str,
        *,
        summary: str | None = None,
        tags: list[str] | None = None,
        user: str | None = None,
        user_id: str | None = None,
    ) -> Memory:
        """Update a memory entry."""
        args: dict[str, Any] = {"id": id}
        if summary is not None:
            args["summary"] = summary
        if tags is not None:
            args["tags"] = ",".join(tags)
        u = user or user_id or self._user
        if u:
            args["user"] = u

        result = await self._transport.call_tool("update_memory", args)
        return _parse_update_result(result, id)

    async def delete(self, id: str) -> bool:
        """Delete a memory entry. Returns True if deleted."""
        try:
            await self._transport.call_tool("delete_memory", {"id": id})
            return True
        except StrataError:
            return False

    async def history(self, id: str) -> list[HistoryEvent]:
        """Get the history of a memory entry."""
        result = await self._transport.call_tool("memory_history", {"id": id})
        return _parse_history_events(result)

    # ── Strata-specific tools (beyond Mem0) ──────────────────────────

    async def find_solutions(
        self,
        query: str,
        *,
        limit: int = 10,
        project: str | None = None,
        format: str = "detailed",
    ) -> list[SearchResult]:
        """Search for solutions to errors or problems."""
        args: dict[str, Any] = {"query": query, "limit": limit, "format": format}
        if project:
            args["project"] = project
        result = await self._transport.call_tool("find_solutions", args)
        return _parse_search_results(result)

    async def find_patterns(
        self,
        query: str,
        *,
        limit: int = 10,
        project: str | None = None,
        format: str = "detailed",
    ) -> list[SearchResult]:
        """Discover recurring patterns."""
        args: dict[str, Any] = {"query": query, "limit": limit, "format": format}
        if project:
            args["project"] = project
        result = await self._transport.call_tool("find_patterns", args)
        return _parse_search_results(result)

    async def find_procedures(
        self,
        query: str,
        *,
        limit: int = 10,
        project: str | None = None,
    ) -> list[SearchResult]:
        """Find step-by-step procedures."""
        args: dict[str, Any] = {"query": query, "limit": limit}
        if project:
            args["project"] = project
        result = await self._transport.call_tool("find_procedures", args)
        return _parse_search_results(result)

    async def ingest(
        self,
        messages: list[dict[str, str]],
        *,
        agent: str = "custom-agent",
        project: str | None = None,
    ) -> IngestResult:
        """Ingest a full conversation through the extraction pipeline."""
        args: dict[str, Any] = {
            "messages": messages,
            "agent": agent,
        }
        if project:
            args["project"] = project
        result = await self._transport.call_tool("ingest_conversation", args)
        return _parse_ingest_result(result)

    async def search_entities(
        self,
        query: str,
        *,
        limit: int = 10,
        type: str | None = None,
        project: str | None = None,
    ) -> list[SearchResult]:
        """Search the entity graph."""
        args: dict[str, Any] = {"query": query, "limit": limit}
        if type:
            args["type"] = type
        if project:
            args["project"] = project
        result = await self._transport.call_tool("search_entities", args)
        return _parse_search_results(result)

    async def store_procedure(
        self,
        title: str,
        steps: list[str],
        *,
        project: str | None = None,
        tags: list[str] | None = None,
    ) -> Memory:
        """Store an explicit procedure."""
        args: dict[str, Any] = {
            "title": title,
            "steps": steps,
        }
        if project:
            args["project"] = project
        if tags:
            args["tags"] = ",".join(tags)
        result = await self._transport.call_tool("store_procedure", args)
        return _parse_store_result(result)

    async def get_project_context(self, project: str) -> str:
        """Get comprehensive context for a project."""
        result = await self._transport.call_tool("get_project_context", {"project": project})
        return result

    async def list_projects(self, *, format: str = "detailed") -> list[Project]:
        """List all indexed projects."""
        result = await self._transport.call_tool("list_projects", {"format": format})
        return _parse_projects(result)

    @classmethod
    def from_env(cls) -> AsyncStrataClient:
        """Create a client configured from environment variables."""
        return cls(
            url=os.environ.get("STRATA_URL"),
            token=os.environ.get("STRATA_TOKEN"),
        )


# ── Response parsers ─────────────────────────────────────────────────
# Strata tools return either JSON (when format=detailed is wired up)
# or formatted text strings. We try JSON first, fall back to text parsing.


def _try_parse_json(text: str) -> Any | None:
    """Try to parse as JSON, return None if not JSON."""
    stripped = text.strip()
    if stripped.startswith(("{", "[")):
        try:
            return json.loads(stripped)
        except json.JSONDecodeError:
            pass
    return None


def _parse_store_result(text: str) -> Memory:
    data = _try_parse_json(text)
    if isinstance(data, dict):
        return Memory(**{k: v for k, v in data.items() if k in Memory.model_fields})

    # Text parsing: "Stored decision: "Use bcrypt with 12 rounds" [tags: auth, security]"
    id_match = re.search(r"\b([0-9a-f]{8}-[0-9a-f-]{27,})\b", text)
    type_match = re.search(r"Stored (\w+):", text)
    return Memory(
        id=id_match.group(1) if id_match else "",
        type=type_match.group(1) if type_match else "",
        summary=text,
    )


def _parse_update_result(text: str, id: str) -> Memory:
    data = _try_parse_json(text)
    if isinstance(data, dict):
        return Memory(**{k: v for k, v in data.items() if k in Memory.model_fields})
    return Memory(id=id, summary=text)


def _parse_search_results(text: str) -> list[SearchResult]:
    data = _try_parse_json(text)
    if isinstance(data, list):
        return [
            SearchResult(**{k: v for k, v in item.items() if k in SearchResult.model_fields})
            for item in data
            if isinstance(item, dict)
        ]
    if isinstance(data, dict) and "results" in data:
        return [
            SearchResult(**{k: v for k, v in item.items() if k in SearchResult.model_fields})
            for item in data["results"]
            if isinstance(item, dict)
        ]

    # Text fallback: split by score patterns and create SearchResults from text
    results: list[SearchResult] = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        score_match = re.search(r"\[([0-9.]+)\]", line)
        score = float(score_match.group(1)) if score_match else 0.0
        results.append(SearchResult(text=line, score=score))
    return results


def _parse_history_events(text: str) -> list[HistoryEvent]:
    data = _try_parse_json(text)
    if isinstance(data, list):
        return [
            HistoryEvent(**{k: v for k, v in item.items() if k in HistoryEvent.model_fields})
            for item in data
            if isinstance(item, dict)
        ]
    # Text fallback
    events: list[HistoryEvent] = []
    for line in text.split("\n"):
        line = line.strip()
        if line:
            events.append(HistoryEvent(event=line))
    return events


def _parse_ingest_result(text: str) -> IngestResult:
    data = _try_parse_json(text)
    if isinstance(data, dict):
        # Pydantic model has aliases for camelCase keys (sessionId, entriesExtracted, etc.)
        # so model_validate accepts both the MCP tool's camelCase output and snake_case.
        return IngestResult.model_validate(data)
    # Text fallback: "Extracted 5 knowledge entries"
    count_match = re.search(r"(\d+)\s+(?:knowledge\s+)?entr", text)
    return IngestResult(
        entries_extracted=int(count_match.group(1)) if count_match else 0,
        summary=text,
    )


def _parse_projects(text: str) -> list[Project]:
    data = _try_parse_json(text)
    if isinstance(data, list):
        return [
            Project(**{k: v for k, v in item.items() if k in Project.model_fields})
            for item in data
            if isinstance(item, dict)
        ]
    if isinstance(data, dict) and "projects" in data:
        return [
            Project(**{k: v for k, v in item.items() if k in Project.model_fields})
            for item in data["projects"]
            if isinstance(item, dict)
        ]
    # Text fallback
    projects: list[Project] = []
    for line in text.split("\n"):
        line = line.strip()
        if line and not line.startswith(("Found", "No ", "─")):
            name_match = re.match(r"(\S+)", line)
            if name_match:
                projects.append(Project(name=name_match.group(1)))
    return projects
